// input format: 1985-10-11 00:00:00.0
// OR Jan 1 1900 12:00AM 
set out = ""
set input = $ZStrip($ZStrip(in,"<=>W"), "*C")
if (($FIND(input,"AM")) > 0 || ($FIND(input,"PM") > 0))
{
	try
	{
		set zVal = $ZDATETIMEH(input,6,4)
		$$$TRACE("ConvertDateTimeToHL7DateString '" _ input _ "', length: " _ $L(input) _ ", err:" _ zVal)
		set out = $ZDATE(zVal,8)
	}
	catch err
	{
		$$$LOGERROR("Value can't be parsed: '" _ input _"', Err: " _ err)
		$$$TRACE("Date from input: " _ $PIECE(input, " ", 1,3))
		set newVal = $PIECE(input, " ", 1,3)
		set out = $ZDATE($ZDATETIMEH(newVal, 6), 8)
		if (out = "")
		{
			set stat = $$$ERROR($$$GeneralError, "Value can't be parsed: " _ input _", Err: " _ err)
		}
	}


}
elseif ($L(input) > 7)  
{
	// provided we have valid input.

	set Year = $E(input,1,4)
	set Month = $E(input,6,7)
	set Day = $E(input,9,10)
	set out=Year _ Month _ Day

}
$$$TRACE("ConvertDateTimeToHL7DateString " _ input _ " converted to " _ out)
return out

// input format: 1985-10-11 00:00:00.0
// OR Jan 1 1900 12:00AM 
set out = ""
set input = $ZStrip($ZStrip(in,"<=>W"),"*C")
if (($FIND(input,"AM")) > 0 || ($FIND(input,"PM") > 0))
{
	try
	{
		set zVal = $ZDATETIMEH(input,6,4)
		$$$TRACE("ConvertDateTimeToHL7DateTimeString '" _ input _ "', length: " _ $L(input) _ ", err:" _ zVal)
		set out = $Translate($ZDATETIME(zVal,8,2)," :.","")

	}
	catch err
	{
		$$$LOGERROR("Value can't be parsed: '" _ input _"', Err: " _ err)
		$$$TRACE("Date from input: " _ $PIECE(input, " ", 1,4))
		set newVal = $PIECE(input, " ", 1,3)
		set newVal = newVal_" "_$PIECE(input,"  ",2)
		$$$TRACE("New Date Time Value: "_newVal)
		set out = $Translate($ZDATETIME($ZDATETIMEH(newVal, 6,4), 8,2)," :.","")

		if (out = "")
		{
			set stat = $$$ERROR($$$GeneralError, "Value can't be parsed: " _ input _", Err: " _ err)
		}
	}


}
elseif ($L(input) > 7)  
{
	// provided we have valid input.

	set Year = $E(input,1,4)
	set Month = $E(input,6,7)
	set Day = $E(input,9,10)
	set Time = $E(input,11,14)
	set out=Year _ Month _ Day _ Time

}
$$$TRACE("ConvertDateTimeToHL7DateTimeString " _ input _ " converted to " _ out)
return out

set out = ""
if ($E(in,1) = "E" && $L(in) > 3 && $F(in,".") < 2)
{
	set out = $E(in,1, 4) _ "." _ $E(in,StrSize(in)-5)
}
elseif ($L(in) > 2 && $F(in,".") < 2)
{
	set out = $E(in,1, 3) _ "." _ $E(in,StrSize(in)-4)
}
else
{
	set out = in
}

set out = ..Strip(out,"<>W")
return out

	set stat = $$$OK
	if (source=""){
		set destination = " "
	}else{
		set destination = source
    }
    Quit stat

// input format: yyyyMMddHHmm, Output format: yyyy-MM-dd hh:mm

set stat = $$$OK

if ($L(source)>0){
	set dob=$ZDATE($ZDATEH($E(source,1,8),8),3)
	if ($L(source)>8){							
		set destination = dob_" "_$E(source,9,10)_":"_$E(source,11,12)		
	}else{
		set destination = dob_" 00:00"
	}		
}else{
	set destination = "1900-01-01 00:00"
}
$$$TRACE("#######PopulateDateTime-- In:  " _ source _ " Out: "_destination )
Quit stat

