// input format: yyyyMMddHHmm, Output format: yyyy-MM-dd hh:mm

set stat = $$$OK

$$$TRACE("#######PopulateSchedDateTime: " _ source )

if ($L(source)>0){
	set dob=$ZDATE($ZDATEH($E(source,1,8),8),3)
	if ($L(source)>8){							
		set destination = dob_" "_$E(source,9,10)_":"_$E(source,11,12)_":00.000"		
	}else{
		set destination = dob_" 00:00:00.000"
	}		
}else{
	set destination = "1900-01-01 00:00:00.000"
}	
Quit stat
